    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The sparse zero cells are markers. Draw 2 between the outermost
    # markers on each row and column, without changing the markers.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == 0]
